<?php
if (!defined('PORTAL_VIEW_ROUTER')) { http_response_code(403); exit; }
title('Duyệt ảnh minh chứng');foreach(rows('SELECT s.*,u.full_name,u.student_id,t.title,t.category FROM submissions s JOIN users u ON s.user_id=u.id JOIN tasks t ON t.id=s.task_id ORDER BY s.id DESC LIMIT 200') as $s){panel($s['student_id'].' · '.$s['full_name'].' · '.$s['title']);echo '<p>'.status($s['status']).' '.e($s['submitted_at']).'</p><p>'.e($s['feedback']).'</p>';if($s['extracted'])echo '<details><summary>Dữ liệu AI đọc được</summary><pre>'.e(json_encode(json_decode($s['extracted'],true),JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE)).'</pre></details>';if($s['image_path'])echo '<a href="index.php?page=photo&id='.(int)$s['id'].'" target="_blank" rel="noopener">Xem ảnh đã nộp</a>';form_open('review');echo '<input type="hidden" name="id" value="'.(int)$s['id'].'"><label>Kết luận<select name="status"><option value="passed">Đạt</option><option value="needs_review">Cần kiểm tra lại</option><option value="rejected">Không đạt</option></select></label>';inputf('Phản hồi','feedback',$s['feedback']??'');submitf('Lưu kết quả');echo '</section>';}
